--- The reverse turns, built at load rather than shipped.
---
--- Writing the same facts out again would have cost 90 KB for M.oh alone, and one pass over
--- a table this size is not measurable next to loading the file at all.
M.oh = {}
for oid, row in pairs(M.obj) do
    local h = row[2]
    if h ~= nil and M.oh[h] == nil then M.oh[h] = oid end
end

M.sh = {}
for qid, rows in pairs(M.steps) do
    for i = 1, #rows do
        local r = rows[i]
        if r[2] ~= nil and M.sh[r[2]] == nil then M.sh[r[2]] = { qid, r[1], r[3] } end
    end
end

return M
